def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda x: sum(row.count(x) for row in grid))
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg: continue
            for dr, dc in ((1,1),(1,-1)):
                p = (r+dr,c+dc)
                if not (0 <= p[0] < h and 0 <= p[1] < w) or grid[p[0]][p[1]] != color: continue
                # extend each end of a diagonal pair, stopping at any non-background cell
                for ar, ac in ((-dr,-dc),(dr,dc)):
                    rr, cc = (r,c) if (ar,ac) == (-dr,-dc) else p
                    while 0 <= rr < h and 0 <= cc < w and grid[rr][cc] == bg:
                        out[rr][cc] = color
                        rr += ar; cc += ac
    return out
